 "content": "def transform(grid):
    """Complete the lone half-width horizontal marker with color 1."""
    out = [row[:] for row in grid]
    width = len(out[0])
    background = None
    for row in out:
        counts = {}
        for value in row:
            counts[value] = counts.get(value, 0) + 1
        if len(counts) == 1:
            background = row[0]
            break
    if background is None:
        return out

    # The partial marker is the row with a single non-background run of
    # exactly half the grid width; extend it with color 1.
    for r, row in enumerate(out):
        if row.count(background) == width // 2 and width % 2 == 0:
            start = next((c for c, value in enumerate(row) if value != background), None)
            if start is not None and all(value == row[start] for value in row[start:start + width // 2]):
                if start == 0:
                    out[r][width // 2:] = [1] * (width // 2)
                    break
                if start == width // 2:
                    out[r][:width // 2] = [1] * (width // 2)
                    break
    return out
